import json

with open('/app/stats.json') as f:
    s = json.load(f)
with open('/app/charts.json') as f:
    ch = json.load(f)

decs = s['decades']
dec_order = ['1970', '1980', '1990', '2000', '2010', '2020']

def fmt(n, d=2): return f"{n:,.{d}f}"

# Decade table rows
dec_rows = ""
for k in dec_order:
    v = decs[k]
    dec_rows += f"""<tr>
  <td><strong>{k}s</strong></td>
  <td>${v['start']:.2f}</td>
  <td>${v['end']:.2f}</td>
  <td class="{'pos' if v['ret'] >= 0 else 'neg'}">{v['ret']:+.1f}%</td>
  <td class="{'pos' if v['cagr'] >= 0 else 'neg'}">{v['cagr']:+.2f}%</td>
  <td>{v['vol']:.1f}%</td>
  <td class="neg">{v['mdd']:.1f}%</td>
  <td>${v['divs']:.3f}</td>
  <td>{v['avg_volume']:,.0f}</td>
</tr>"""

# Drawdown table
dd_rows = ""
crisis_map = [
    ('2007-07-19', 'Global Financial Crisis'),
    ('1973-01-19', '1973–74 Oil Crisis / Recession'),
    ('2000-10-02', 'Dot-com Bust / 9-11 Aftermath'),
    ('1989-10-09', 'Early 1990s Recession / S&L Crisis'),
    ('2020-02-19', 'COVID-19 Pandemic Crash'),
    ('1987-03-06', 'Black Monday (Oct 1987)'),
    ('1983-06-17', 'Mid-1980s Consolidation'),
    ('2014-07-03', 'Costco Split / Oil Shock Period'),
]
crisis_dict = dict(crisis_map)

for e in s['top_drawdowns']:
    context = crisis_dict.get(e['peak_date'], 'Cyclical drawdown')
    rec = e['recovery_date'] if e['recovery_date'] else '<em>Not fully recovered in sample</em>'
    dd_rows += f"""<tr>
  <td class="neg"><strong>{e['dd']:.1f}%</strong></td>
  <td>{e['peak_date']}</td>
  <td>${e['peak']:.2f}</td>
  <td>{e['trough_date']}</td>
  <td>${e['trough']:.2f}</td>
  <td>{e['days_to_trough']}</td>
  <td>{rec}</td>
  <td>{context}</td>
</tr>"""

# Sub-period CAGR table (from printed values)
subperiod_rows = """
<tr><td>1972–1990</td><td>$1.22 → $3.01</td><td>18.6</td><td>4.95%</td></tr>
<tr><td>1990–2000</td><td>$4.89 → $34.01</td><td>11.0</td><td class="pos">19.30%</td></tr>
<tr><td>2000–2010</td><td>$32.25 → $34.69</td><td>11.0</td><td>0.66%</td></tr>
<tr><td>2010–2020</td><td>$32.48 → $113.41</td><td>11.0</td><td class="pos">12.05%</td></tr>
<tr><td>2020–2026</td><td>$116.38 → $305.99</td><td>6.2</td><td class="pos">16.91%</td></tr>
<tr><td>2000–2026</td><td>$32.25 → $305.99</td><td>26.2</td><td>8.97%</td></tr>
<tr class="total-row"><td><strong>Full Period (1972–2026)</strong></td><td>$1.22 → $305.99</td><td>53.8</td><td class="pos"><strong>10.81%</strong></td></tr>
"""

# Stock splits table
splits_rows = """
<tr><td>1983-02-11</td><td>1.333×</td></tr>
<tr><td>1983-08-11</td><td>1.500×</td></tr>
<tr><td>1987-05-11</td><td>2.000×</td></tr>
<tr><td>1994-05-31</td><td>1.133×</td></tr>
<tr><td>2000-05-11</td><td>3.000×</td></tr>
<tr><td>2005-10-03</td><td>1.142×</td></tr>
"""

# Dividend yield history - sample points
div_yield = s['div_yield_trend']
div_yield_rows = ""
samples = [1977, 1985, 1990, 1995, 2000, 2005, 2008, 2010, 2015, 2020, 2023, 2024, 2025]
for yr in samples:
    pt = next((d for d in div_yield if d['year'] == yr), None)
    if pt:
        div_yield_rows += f"<tr><td>{pt['year']}</td><td>${pt['div']:.3f}</td><td>${pt['close']:.2f}</td><td>{pt['yield']:.2f}%</td></tr>"

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>American Express (AXP) Historical Stock Performance Report: 1972–2026</title>
<style>
  * {{ box-sizing: border-box; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    background: #f5f6f8;
    color: #111827;
    margin: 0;
    line-height: 1.6;
  }}
  .container {{ max-width: 1180px; margin: 0 auto; padding: 40px 28px; }}
  header.hero {{
    background: linear-gradient(135deg, #012169 0%, #0f6efd 100%);
    color: white;
    padding: 44px 40px;
    border-radius: 12px;
    margin-bottom: 32px;
    box-shadow: 0 6px 20px rgba(1,33,105,0.18);
  }}
  header.hero h1 {{ margin: 0 0 12px 0; font-size: 30px; letter-spacing: -0.02em; }}
  header.hero .subtitle {{ font-size: 16px; opacity: 0.92; max-width: 900px; }}
  header.hero .meta {{ margin-top: 18px; font-size: 13px; opacity: 0.85; }}
  section {{
    background: #ffffff;
    border-radius: 10px;
    padding: 32px 36px;
    margin-bottom: 26px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.04);
  }}
  h2 {{
    font-size: 22px;
    color: #012169;
    margin-top: 0;
    border-bottom: 2px solid #eaecf0;
    padding-bottom: 10px;
  }}
  h3 {{ font-size: 16px; color: #1f2937; margin-top: 22px; margin-bottom: 8px; }}
  p {{ margin: 0 0 14px 0; }}
  .kpi-dashboard {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 14px;
    margin: 20px 0 8px 0;
  }}
  .kpi-card {{
    background: linear-gradient(135deg, #f8fafc 0%, #eef2ff 100%);
    border: 1px solid #e5e7eb;
    border-radius: 10px;
    padding: 20px 18px;
    text-align: center;
  }}
  .kpi-label {{
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #6b7280;
    margin-bottom: 8px;
    font-weight: 600;
  }}
  .kpi-value {{
    font-size: 26px;
    font-weight: 700;
    color: #012169;
    letter-spacing: -0.02em;
  }}
  .kpi-value.neg {{ color: #b91c1c; }}
  .kpi-value.pos {{ color: #15803d; }}
  .kpi-sub {{ font-size: 11px; color: #6b7280; margin-top: 6px; }}
  table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0;
    font-size: 13px;
  }}
  th {{
    background: #f3f4f6;
    text-align: left;
    padding: 10px 12px;
    font-weight: 600;
    color: #374151;
    border-bottom: 2px solid #d1d5db;
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }}
  td {{ padding: 10px 12px; border-bottom: 1px solid #eef0f3; }}
  tr:hover {{ background: #fafbfc; }}
  tr.total-row td {{ background: #eff6ff; font-weight: 600; }}
  .pos {{ color: #15803d; font-weight: 600; }}
  .neg {{ color: #b91c1c; font-weight: 600; }}
  .chart {{ width: 100%; height: auto; margin: 14px 0; }}
  .callout {{
    background: #eff6ff;
    border-left: 4px solid #0f6efd;
    padding: 14px 18px;
    margin: 16px 0;
    border-radius: 4px;
    font-size: 14px;
  }}
  .callout.warn {{ background: #fef3c7; border-left-color: #f59e0b; }}
  .callout.danger {{ background: #fee2e2; border-left-color: #dc2626; }}
  .two-col {{ display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }}
  .takeaway-grid {{ display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 14px; }}
  .takeaway {{
    background: #f9fafb;
    border-radius: 8px;
    padding: 16px;
    border-top: 3px solid #0f6efd;
  }}
  .takeaway h4 {{ margin: 0 0 6px 0; font-size: 13px; color: #012169; }}
  .takeaway p {{ margin: 0; font-size: 13px; color: #374151; }}
  footer {{
    text-align: center;
    color: #6b7280;
    font-size: 12px;
    margin-top: 30px;
    padding: 20px 0;
  }}
  @media (max-width: 900px) {{
    .kpi-dashboard {{ grid-template-columns: repeat(2, 1fr); }}
    .two-col, .takeaway-grid {{ grid-template-columns: 1fr; }}
    section {{ padding: 22px 20px; }}
  }}
</style>
</head>
<body>
<div class="container">

<header class="hero">
  <h1>American Express (AXP) Historical Stock Performance Report</h1>
  <div class="subtitle">A comprehensive analysis of American Express stock performance spanning over 50 years of daily trading data — covering price trends, volatility, dividend history, and key market events.</div>
  <div class="meta">Coverage: {s['first_date']} → {s['last_date']} &nbsp;|&nbsp; {s['total_rows']:,} trading days &nbsp;|&nbsp; Audience: Investors &nbsp;|&nbsp; Source: Split/dividend-adjusted closing prices</div>
</header>

<section>
  <h2>At-a-Glance: Key Performance Indicators</h2>
  <p>The dashboard below summarizes AXP's performance over the entire {s['years']:.1f}-year dataset. All figures are computed directly from daily adjusted closing prices.</p>
  <div class="kpi-dashboard">
    <div class="kpi-card">
      <div class="kpi-label">Cumulative Return</div>
      <div class="kpi-value pos">{s['cum_return']:,.0f}%</div>
      <div class="kpi-sub">${s['first_close']:.2f} → ${s['last_close']:.2f}</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">CAGR</div>
      <div class="kpi-value pos">{s['cagr']:.2f}%</div>
      <div class="kpi-sub">Full {s['years']:.1f}-year period</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Max Drawdown</div>
      <div class="kpi-value neg">{s['max_dd']:.1f}%</div>
      <div class="kpi-sub">{s['peak_before_dd_date']} → {s['max_dd_date']}</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Annualized Volatility</div>
      <div class="kpi-value">{s['ann_vol']:.1f}%</div>
      <div class="kpi-sub">Daily σ × √252</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Total Dividends / Share</div>
      <div class="kpi-value pos">${s['total_divs']:.2f}</div>
      <div class="kpi-sub">{s['num_div_events']} distributions</div>
    </div>
  </div>
</section>

<section id="executive-overview">
  <h2>1. Executive Overview</h2>
  <p>American Express (NYSE: AXP) delivered a <strong>{s['cum_return']:,.0f}% cumulative return</strong> over the {s['years']:.1f}-year window from June 1972 through March 2026, compounding at <strong>{s['cagr']:.2f}% per year</strong>. A single share bought at the adjusted price of <strong>${s['first_close']:.2f}</strong> in mid-1972 would close the sample at <strong>${s['last_close']:.2f}</strong>, after enduring six stock splits, 197 dividend payments, and multiple drawdowns exceeding 45%.</p>

  <p>The stock recorded its all-time intraday peak close of <strong>${s['ath']:.2f}</strong> on <strong>{s['ath_date']}</strong>, and its adjusted all-time low of <strong>${s['atl']:.4f}</strong> on <strong>{s['atl_date']}</strong> at the depths of the 1973–74 bear market. As of the latest trading day ({s['last_date']}), AXP trades at <strong>${s['last_close']:.2f}</strong> — approximately {(s['last_close']/s['ath']-1)*100:.1f}% from its recent all-time high, after a sharp correction from the December 2025 peak.</p>

  <div class="takeaway-grid">
    <div class="takeaway">
      <h4>Long-Run Compounder</h4>
      <p>Double-digit CAGR across five decades places AXP among the more resilient long-term compounders in U.S. financial services — despite its cyclical exposure.</p>
    </div>
    <div class="takeaway">
      <h4>Cyclical Risk Is Real</h4>
      <p>The –{abs(s['max_dd']):.0f}% drawdown during the Global Financial Crisis and two other >45% corrections underline that AXP is not a low-volatility defensive name.</p>
    </div>
    <div class="takeaway">
      <h4>Growing Dividend</h4>
      <p>Cumulative cash dividends of <strong>${s['total_divs']:.2f}</strong> per share, with annual payouts trending from cents in the 1970s to over $3 per share in 2025, demonstrate a maturing income profile.</p>
    </div>
  </div>
</section>

<section id="price-trend-analysis">
  <h2>2. Long-Term Price Trend Analysis</h2>
  <p>The multi-decade price trajectory, plotted on a logarithmic scale to make growth rates comparable across different price levels, reveals five clearly distinct phases: a choppy sideways-to-lower 1970s, a powerful 1980s and 1990s expansion, the boom-bust cycle of the 2000s, a disciplined 2010s recovery, and the post-pandemic acceleration through 2024–25.</p>

  {ch['price']}

  <h3>2.1 Compounded Growth by Sub-Period</h3>
  <p>Dissecting the full-period {s['cagr']:.2f}% CAGR into discrete sub-windows reveals that AXP's long-term return is not evenly distributed — two flat/down periods (1970s and 2000s) bookend decades of outperformance.</p>
  <table>
    <thead><tr><th>Period</th><th>Price Trajectory</th><th>Years</th><th>CAGR</th></tr></thead>
    <tbody>{subperiod_rows}</tbody>
  </table>

  <h3>2.2 Bull and Bear Phases</h3>
  <ul>
    <li><strong>Bear I — 1973–1974 ({fmt(s['top_drawdowns'][1]['dd'])}%):</strong> AXP declined from ${s['top_drawdowns'][1]['peak']:.2f} to ${s['top_drawdowns'][1]['trough']:.4f} alongside the oil crisis and "Nifty Fifty" de-rating. Recovery to prior highs did not occur until <strong>1982</strong> — nearly a decade.</li>
    <li><strong>Bull I — 1982–1989:</strong> AXP rose more than 10x as disinflation, financial deregulation, and the charge-card franchise drove earnings.</li>
    <li><strong>Bear II — 1989–1990 (–53.9%):</strong> S&L crisis and early-90s recession triggered a one-year drawdown.</li>
    <li><strong>Bull II — 1990s:</strong> The strongest sustained run in AXP history, 1990s CAGR of {decs['1990']['cagr']:.2f}%.</li>
    <li><strong>Bear III — 2000–2001 (–59.1%):</strong> Dot-com bust and post-9/11 travel shock crushed card volumes.</li>
    <li><strong>Bear IV — 2007–2009 ({s['max_dd']:.1f}%):</strong> The deepest drawdown on record; AXP fell from ${s['peak_before_dd']:.2f} to ${s['top_drawdowns'][0]['trough']:.2f}. Full recovery took until <strong>April 2012</strong>.</li>
    <li><strong>Bull III — 2009–2014:</strong> Aggressive recovery coincided with charge-off normalization and strong buyback activity.</li>
    <li><strong>Consolidation — 2014–2017 (–45.4%):</strong> Loss of Costco co-brand partnership, brand repositioning costs, and energy-sector exposure compressed returns.</li>
    <li><strong>Bear V — 2020 (–49.6%):</strong> COVID-19 collapse — but unusually rapid: trough-to-recovery in just 12 months.</li>
    <li><strong>Bull IV — 2020–2025:</strong> Post-pandemic spending boom propelled AXP to the ${s['ath']:.0f} ATH in December 2025 before the early 2026 correction.</li>
  </ul>

  <div class="callout">
    <strong>Key observation:</strong> Every major bear phase has been fully recovered to new highs. The longest wait to reclaim a peak was the 1973 high, which was not surpassed until 1982 (≈9 years). Investors who held through these drawdowns realized the full {s['cum_return']:,.0f}% long-run return.
  </div>
</section>

<section id="volatility-risk">
  <h2>3. Volatility &amp; Risk Assessment</h2>
  <p>AXP's full-period <strong>annualized volatility of {s['ann_vol']:.2f}%</strong> (daily σ = {s['daily_vol']:.2f}%) is elevated relative to the S&P 500's long-run ~16–18% — consistent with its classification as a cyclical financial name with consumer-credit exposure. Volatility is not constant: the 2000s recorded the highest decade-level volatility at {decs['2000']['vol']:.1f}%, driven by the GFC, while the 2010s marked a calmer regime at {decs['2010']['vol']:.1f}%.</p>

  {ch['drawdown']}

  <h3>3.1 Worst Drawdown Episodes (Ranked)</h3>
  <p>The table below ranks the eight largest peak-to-trough closing-price drawdowns observed in the dataset, with associated timing and recovery dates. The 2008 Global Financial Crisis stands alone as the single worst episode for AXP shareholders.</p>
  <table>
    <thead>
      <tr>
        <th>Drawdown</th><th>Peak Date</th><th>Peak Price</th>
        <th>Trough Date</th><th>Trough Price</th><th>Days to Trough</th>
        <th>Recovery Date</th><th>Context</th>
      </tr>
    </thead>
    <tbody>{dd_rows}</tbody>
  </table>

  <div class="callout danger">
    <strong>Risk flag — 2007–2009 drawdown:</strong> AXP's {s['max_dd']:.1f}% peak-to-trough decline over 596 days exceeded the S&P 500's ~–57% GFC drawdown, reflecting the market's severe repricing of consumer-credit risk. The stock did not regain its July 2007 peak until <strong>April 2012</strong>, a <em>4.8-year</em> underwater period.
  </div>

